/* Indian-format rupees without relying on toLocaleString('en-IN') */
function inr(n){
  const neg=n<0; let s=String(Math.round(Math.abs(n)));
  if(s.length>3){const last=s.slice(-3);let rest=s.slice(0,-3);rest=rest.replace(/\B(?=(\d{2})+(?!\d))/g,',');s=rest+','+last;}
  return (neg?'−':'')+'₹'+s;
}
function num(n){return inr(n).replace('₹','');}
function pct(x,d){return (x*100).toFixed(d===undefined?1:d)+'%';}

